/**
 * Reference output of inkvec 0.2.7's band merge (`merge_bands_with`, region recovery on, the
 * default work cap) and of its carve (`carve_residual_features_with_detail_noise`, `min_size`
 * 2, no detail noise) run on inkvec's merge result, for corpus images at 128 px (whole, or a
 * crop), each fed inkvec's own pre-merge labels and palette. Generated data.
 *
 * The image over white is `rgb8` (8-bit levels, level/255 in single precision) or `rgb32`
 * (single-precision bits), deflated and base64; a label map is 16-bit values, deflated and
 * base64. The carve's fills are listed as `[label, line]` where they differ from the merge's
 * (a refitted parent) or are new (a minted feature). A fill is inkvec's line
 * `kind interp g0 … g5 c0(3) c1(3) n [offset r g b]… | chi2 params cost`, its points in inkvec's
 * frame (pixel centers at integer indices; Trazor's are these plus ½): `x0 y0 x1 y1 0 0` for a
 * linear ramp, `cx cy r aspect angle 0` for a radial one.
 */

/** One image: inkvec's input and its merge and carve output. */
export interface BandsRef {
  name: string
  w: number
  h: number
  sigma: number
  lambda: number
  rgb8?: string
  rgb32?: string
  labels: string
  inks: number[]
  /** Work the merge spent. */
  spent: number
  merge: { labels: string; ink: number[]; fills: string[] }
  minted: number
  /** Further merge runs of the same input: region recovery on or off, under a work cap (null: the default). */
  variants?: {
    regions: boolean
    cap: number | null
    spent: number
    stopped: boolean
    labels: string
    ink: number[]
    fills: string[]
  }[]
  carve: { labels: string; ink: number[]; fills: [number, string][] }
}

